private async Task CachePreviousFinancialYearVoucherAuthorityAsync(
    ClientProfile client,
    TallyCompanyInfo company)
{
    var previousFy = ShiftFinancialYear(client.FinancialYear, -1);
    if (previousFy.Length == 0) return;
    var (fromDate, toDate) = FinancialYearDates(previousFy);
    var booksFrom = TallyCompanyInfo.ParseTallyDate(company.BooksFrom);
    if (booksFrom.HasValue && booksFrom.Value.Date > toDate.Date) return;

    try
    {
        ConnectionStatus = "Tally connected • caching previous-FY Fixed Asset evidence";
        var index = await _httpService.ExportVoucherIndexFreshAsync(company, fromDate, toDate);
        var full = await _httpService.ExportCompleteVoucherXmlAuthorityAsync(company, index, fromDate, toDate);
        _repository.ReplaceVoucherIndex(company.CompanyKey, previousFy, index);
        _repository.ReplaceVoucherXmlAuthority(company.CompanyKey, previousFy, full);
    }
    catch (Exception exception)
    {
        LastOperationStatus = $"Current FY authority ready; previous-FY cache {previousFy} was not refreshed: {exception.Message}";
    }
}

private static string ShiftFinancialYear(string financialYear, int offset)
{
    var parts = (financialYear ?? string.Empty).Split('-', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    if (parts.Length == 0 || !int.TryParse(parts[0], out var startYear)) return string.Empty;
    startYear += offset;
    if (startYear < 1900 || startYear > 9998) return string.Empty;
    var endYear = startYear + 1;
    var second = parts.Length > 1 && parts[1].Length <= 2 ? (endYear % 100).ToString("00") : endYear.ToString();
    return $"{startYear}-{second}";
}

